<?php namespace App\Repositories\ProductVariant; use App\Models\ProductVariant; class ProductVariantRepository implements ProductVariantRepositoryInterface {public function paginate(array $f){return ProductVariant::query()->with(['product:id,name','unit:id,name,short_name'])->when($f['search']??null,fn($q,$s)=>$q->where(fn($x)=>$x->where('name','like',"%$s%")->orWhere('sku','like',"%$s%")->orWhere('barcode','like',"%$s%")))->when($f['product_id']??null,fn($q,$id)=>$q->where('product_id',$id))->latest()->paginate(15)->withQueryString();} public function create(array $d):ProductVariant{return ProductVariant::create($d);} public function update(ProductVariant $v,array $d):ProductVariant{$v->update($d);return $v->refresh();} public function delete(ProductVariant $v):void{$v->delete();}}